// === Tab: mySketch.js ===
/*
 * =====================================================================================
 * ACTIVIDAD 2: HEADER INTERACTIVO - SISTEMAS INTERACTIVOS
 * CLIENTE FICTICIO: AG TELECOMUNICACIONES
 * =====================================================================================
 * 
 * DESCRIPCIÓN DEL SISTEMA Y UX:
 * Este componente es una cabecera web ("Hero Section") 100% responsiva. Su objetivo 
 * es comunicar visualmente el concepto de "hiperconectividad y transferencia masiva de datos" 
 * a través de un ecosistema visual vanguardista y minimalista.
 * 
 * ARQUITECTURA DE ANIMACIONES:
 * 1. Nodos de Red (Fondo): Un sistema de partículas autónomas con deriva vectorial.
 * 2. Señal Continua (Ondas): Curvas trigonométricas que dibujan un flujo volumétrico.
 * 3. Ráfagas (Meteoros): Evento asíncrono que inyecta haces de luz multidireccionales cada 3s.
 * 4. Gravedad Cero (Tipografía): El bloque de marca utiliza una traslación senoidal continua.
 * 
 * MAPEO DE INTERACCIÓN:
 * - Modulación de Señal (Macro): El mapeo continuo del cursor altera la topología de las ondas.
 *   X = Densidad de la señal (1 a 15 vectores simultáneos). Y = Amplitud de la frecuencia.
 * - Feedback de Proximidad (Micro): Los nodos del fondo tienen un "Trigger" radial. 
 *   Al detectar el puntero (Hover), escalan su tamaño y opacidad para confirmar la interacción.
 * =====================================================================================
 */

// --- ESTADO GLOBAL DEL SISTEMA ---
let time = 0; // Motor trigonométrico: impulsa el desplazamiento de ondas y flotación.
let particles = []; // Memoria (Array) para el renderizado del ecosistema de nodos.
let meteors = []; // Memoria (Array) para la recolección de ráfagas de datos activas.
let lastMeteorTime = 0; // Timestamp para calcular el intervalo del evento síncrono.

function setup() {
  // 1. INICIALIZACIÓN DEL VIEWPORT (Responsividad)
  // Utilizamos las variables globales del DOM de p5.js para inyectar el canvas
  // ocupando el 100% del espacio de la ventana del navegador.
  createCanvas(windowWidth, windowHeight);

  // 2. CONFIGURACIÓN DEL SISTEMA DE DISEÑO (Tipografía y Maquetación)
  textAlign(CENTER, CENTER); // Anclaje central para facilitar el cálculo de coordenadas UI
  textFont('Syne'); // Tipografía vanguardista (debe estar enlazada en el <head> del HTML)

  // --- HACK CSS DESDE JAVASCRIPT ---
  // Eliminamos los marcos blancos y barras de scroll forzando el estilo del body
  document.body.style.margin = '0';
  document.body.style.padding = '0';
  document.body.style.overflow = 'hidden';
  document.body.style.backgroundColor = '#0A0C14'; // Fondo oscuro base

  // Forzamos el canvas a comportarse como bloque para quitar el margen inferior
  let lienzos = document.getElementsByTagName('canvas');
  if (lienzos.length > 0) {
    lienzos[0].style.display = 'block';
  }

	// 3. POBLACIÓN DEL ENTORNO (Instanciación de Objetos)
  // Inyectamos 120 instancias de la clase Particle en nuestro arreglo al cargar el sitio.
  for (let i = 0; i < 120; i++) {
    particles.push(new Particle());
  }
}

function draw() {
  // 4. PIPELINE DE RENDERIZADO (Se ejecuta a ~60 FPS)

  // Limpieza del Frame: Un fondo azul noche (Casi negro) para maximizar el contraste
  // jerárquico frente a los elementos luminosos de la interfaz.
  background(10, 12, 20); 

  // Compositing: Activamos el modo de fusión aditiva. Al sumar los valores RGB 
  // de las transparencias superpuestas, logramos un efecto de "Luz de Pantalla" (Glow)
  // sin necesidad de filtros costosos para el procesador.
  blendMode(ADD);

  // --- CAPA 1: ECOSISTEMA DE NODOS INTERACTIVOS ---
  // Bucle de actualización y dibujo para la capa más profunda del lienzo.
  for (let i = 0; i < particles.length; i++) {
    particles[i].update();
    particles[i].display();
  }

  // --- CAPA 2: EVENTO SÍNCRONO (RÁFAGAS DE DATOS) ---
  // Lógica temporal: Comparamos el tiempo actual (millis) con el último registro.
  // Si la diferencia supera los 3000ms, disparamos el evento.
  if (millis() - lastMeteorTime > 3000) {
    spawnMeteors();
    lastMeteorTime = millis(); // Reiniciamos el cronómetro
  }

  // Bucle Inverso: Fundamental para la gestión de memoria (Garbage Collection).
  // Iteramos hacia atrás para poder destruir objetos de la memoria (splice)
  // sin alterar los índices de los elementos restantes en el arreglo.
  for (let i = meteors.length - 1; i >= 0; i--) {
    meteors[i].update();
    meteors[i].display();

    if (meteors[i].isOffScreen()) {
      meteors.splice(i, 1); // Liberación de memoria cuando el objeto sale del viewport
    }
  }

  // --- CAPA 3: FLUJO DE DATOS MODULADO POR EL USUARIO (ONDAS) ---
  // Input Binding: Traducimos las coordenadas X/Y del ratón a parámetros visuales
  let numWaves = floor(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 1, 15)); 
  numWaves = constrain(numWaves, 1, 15); // Evita colapsos si el ratón sale del canvas
  let amplitude = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 10, 180);

  noFill(); // Desactivamos el relleno para renderizar solo la estructura alámbrica (Wireframe)

  // Generación Multi-onda
  for (let i = 0; i < numWaves; i++) {
    // Algoritmo de Color Fluido: Usamos funciones trigonométricas desfasadas 
    // para crear un espectro que viaja desde el cian tecnológico hacia acentos magenta.
    let r = map(sin(time * 0.5 + i * 0.3), -1, 1, 20, 150); 
    let g = map(cos(time * 0.3 + i * 0.2), -1, 1, 100, 255); 
    let b = 255; 

    stroke(r, g, b, 80); 

    // Profundidad Óptica: Las ondas iteradas al final son más finas, simulando cercanía
    let currentWeight = map(i, 0, numWaves, 6, 1);
    strokeWeight(currentWeight);

    // Trazado del vector a lo largo del eje X
    beginShape();
    for (let x = 0; x <= width; x += 10) {
      let phase = i * 0.25; // Desfase paramétrico para separar las curvas
      let depthFactor = map(i, 0, numWaves, 1, 0.4); // Reducción de amplitud por perspectiva

      // Ecuación principal de la onda senoidal
      let y = height / 2 + sin(x * 0.005 + time + phase) * amplitude * depthFactor;
      vertex(x, y);
    }
    endShape();
  }

  // 5. RESTAURACIÓN DEL PIPELINE
  // Apagamos la fusión aditiva. Esto es crítico para que la tipografía 
  // se renderice con opacidad sólida del 100% y garantice su accesibilidad/legibilidad.
  blendMode(BLEND);

  time += 0.03; // Avance del motor de tiempo

  // --- CAPA 4: COMPONENTE DE MARCA (UI CENTRAL) ---
  // Modulación vertical constante para simular ingravidez
  let floatY = sin(time * 1.5) * 12; 

  push(); // Aislamos la matriz de transformación
  translate(width / 2, height / 2 + floatY); // Traslación al centro + flotación

  // Construcción del Isotipo "AG"
  fill(255);
  noStroke();
  textStyle(BOLD); 
  textSize(64);
  text("AG", 0, -30); 

  // Construcción del Logotipo
  textStyle(NORMAL);
  textSize(20);
  text("TELECOMUNICACIONES", 0, 20); 

  // Construcción del Motto (Gris azulado para establecer jerarquía secundaria)
  fill(130, 140, 160); 
  textSize(16);
  text("Conectando el futuro, nuestra red es la m\u00E1s avanzada.", 0, 60);
  pop(); // Restauramos la matriz original
}

// --- EVENT LISTENERS DEL DOM ---
// Garantiza que la interfaz sea responsiva si el usuario redimensiona la ventana del navegador.
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}


/*
 * =====================================================================================
 * CLASE METEOR: GESTIÓN DE RÁFAGAS DE DATOS (EVENTOS SÍNCRONOS)
 * =====================================================================================
 */
function spawnMeteors() {
  // Instancia un grupo de haces de luz (entre 4 y 8) para crear impacto visual
  let count = floor(random(4, 8)); 
  for (let i = 0; i < count; i++) {
    meteors.push(new Meteor());
  }
}

class Meteor {
  constructor() {
    this.history = []; // Buffer de memoria para renderizar la estela cinética (trail)
    let edge = floor(random(3)); // Selección de origen: 0=Top, 1=Right, 2=Left
    let minSpeed = 3;
    let maxSpeed = 8; // Velocidades altas para denotar "Banda Ancha / Transferencia Rápida"

    // Asignación de vectores de velocidad basados en el punto de aparición
    if (edge === 0) { 
      this.x = random(width); this.y = -50;
      this.vx = random(-maxSpeed, maxSpeed); this.vy = random(minSpeed, maxSpeed);
    } else if (edge === 1) { 
      this.x = width + 50; this.y = random(height / 2);
      this.vx = random(-maxSpeed, -minSpeed); this.vy = random(minSpeed, maxSpeed);
    } else { 
      this.x = -50; this.y = random(height / 2);
      this.vx = random(minSpeed, maxSpeed); this.vy = random(minSpeed, maxSpeed);
    }
  }

  update() {
    this.history.push({ x: this.x, y: this.y }); // Guarda la coordenada actual en el buffer
    if (this.history.length > 15) this.history.shift(); // Limita el buffer a 15 frames
    this.x += this.vx; this.y += this.vy; // Aplica la física de movimiento
  }

  display() {
    noFill();
    // Renderizado del rastro (Trail). Interpolamos grosor y opacidad 
    // a lo largo del historial para lograr una caída visual (fade-out) orgánica.
    for (let i = 1; i < this.history.length; i++) {
      let alpha = map(i, 0, this.history.length, 0, 200);
      stroke(150, 220, 255, alpha); 
      let weight = map(i, 0, this.history.length, 1, 4);
      strokeWeight(weight);
      line(this.history[i - 1].x, this.history[i - 1].y, this.history[i].x, this.history[i].y);
    }
  }

  // Función booleana para optimización de recursos (Destrucción de instancias inútiles)
  isOffScreen() {
    return (this.x < -100 || this.x > width + 100 || this.y > height + 100);
  }
}

/*
 * =====================================================================================
 * CLASE PARTICLE: GESTIÓN DE NODOS DE RED (ECOSISTEMA DE FONDO)
 * =====================================================================================
 */
class Particle {
  constructor() {
    this.x = random(width); this.y = random(height);
    this.vx = random(-0.5, 0.5); this.vy = random(-0.5, 0.5); // Micro-flotación
    this.size = random(1, 3);
  }

  update() {
    this.x += this.vx; this.y += this.vy;
    // Lógica de "Mundo Infinito": Envoltura de pantalla para evitar instanciar nuevos objetos
    if (this.x < 0) this.x = width; if (this.x > width) this.x = 0;
    if (this.y < 0) this.y = height; if (this.y > height) this.y = 0;
  }

  display() {
    // Teorema de Pitágoras para detección de proximidad del cursor (Hitbox invisible)
    let d = dist(this.x, this.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let currentSize = this.size;
    var alpha = 50; 

    // MICRO-INTERACCIÓN (HOVER): Rango de detección de 120px
    if (d < 120) {
      // Inversión de escala: A menor distancia, mayor es el factor de reacción visual
      let hoverFactor = map(d, 0, 120, 1, 0); 
      currentSize = this.size + (hoverFactor * 6); // Expansión geométrica
      alpha = 50 + (hoverFactor * 150); // Aumento de emisión de luz

      // Renderizado del Halo Reactivo
      noStroke();
      fill(100, 200, 255, alpha * 0.3); 
      ellipse(this.x, this.y, currentSize * 2.5);
    }

    // Renderizado del Nodo Base
    noStroke();
    fill(150, 220, 255, alpha); 
    ellipse(this.x, this.y, currentSize);
  }
}

